from fastapi import FastAPI, Request, WebSocket, HTTPException
from fastapi.exceptions import RequestValidationError, ResponseValidationError, WebSocketRequestValidationError
from pydantic import BaseModel
import pytest
from fastapi.testclient import TestClient

app = FastAPI()

class Item(BaseModel):
    name: str
    id: int

@app.get("/users/{user_id}")
async def get_user(user_id: int):
    return {"user_id": user_id}

@app.post("/items/")
async def create_item(item: Item):
    # To trigger ResponseValidationError, we return something that doesn't match the response model
    # But we need to define a response_model for that.
    return {"name": "Widget"} # Missing 'id'

@app.websocket("/ws/{item_id}")
async def websocket_endpoint(websocket: WebSocket, item_id: int):
    await websocket.accept()
    await websocket.send_text(f"Item {item_id}")

# We need to trigger these exceptions. 
# RequestValidationError is usually handled by FastAPI and returns 422.
# To see the traceback, we can raise it manually or use a custom exception handler that prints it.

def test_request_validation_error():
    print("\n--- Testing RequestValidationError ---")
    try:
        # Simulate what FastAPI does when validation fails
        raise RequestValidationError(errors=[{"type": "int_parsing", "loc": ("path", "user_id"), "msg": "Input should be a valid integer", "input": "invalid"}])
    except RequestValidationError as e:
        print(e)

def test_response_validation_error():
    print("\n--- Testing ResponseValidationError ---")
    try:
        raise ResponseValidationError(errors=[{"type": "missing", "loc": ("response", "id"), "msg": "Field required", "input": {"name": "Widget"}}])
    except ResponseValidationError as e:
        print(e)

def test_websocket_request_validation_error():
    print("\n--- Testing WebSocketRequestValidationError ---")
    try:
        raise WebSocketRequestValidationError(errors=[{"type": "int_parsing", "loc": ("path", "item_id"), "msg": "Input should be a valid integer", "input": "invalid"}])
    except WebSocketRequestValidationError as e:
        print(e)

if __name__ == "__main__":
    test_request_validation_error()
    test_response_validation_error()
    test_websocket_request_validation_error()
